const getEstimateInventoryItems = `-- name: GetEstimateInventoryItems :many
SELECT
  id,
  tenant_id,
  estimate_id,
  category,
  item_name,
  volume_cf,
  qty,
  is_custom,
  created_at,
  updated_at
FROM estimate_inventory_item
WHERE tenant_id = $1
  AND estimate_id = $2
ORDER BY lower(category), lower(item_name), id
`

type GetEstimateInventoryItemsParams struct {
	TenantID   uuid.UUID `json:"tenant_id"`
	EstimateID uuid.UUID `json:"estimate_id"`
}

func (q *Queries) GetEstimateInventoryItems(ctx context.Context, arg GetEstimateInventoryItemsParams) ([]EstimateInventoryItem, error) {
	rows, err := q.db.Query(ctx, getEstimateInventoryItems, arg.TenantID, arg.EstimateID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []EstimateInventoryItem{}
	for rows.Next() {
		var i EstimateInventoryItem
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.EstimateID,
			&i.Category,
			&i.ItemName,
			&i.VolumeCf,
			&i.Qty,
			&i.IsCustom,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

